export function SampleData({
  title = "{{title}}",
  description = "{{description}}",
  datasetName = "{{datasetName}}",
  style = "{{style}}",
  accent = "{{accent}}",
}) {
  const rows = [
    ["North", "£48,200", "+12%"],
    ["South", "£31,900", "+4%"],
    ["East", "£55,600", "+18%"],
  ];
  const bars = [52, 78, 36, 90];
  const cards = [
    ["Revenue", "£135.7k"],
    ["Orders", "1,204"],
    ["Growth", "+11%"],
  ];
  return (
    <div style={{ font: "16px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, maxWidth: 380, borderRadius: 14, border: "1px solid #24143018" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10, marginBottom: 14 }}>
        <div>
          <h3 style={{ margin: "0 0 4px", fontSize: 15, fontWeight: 700 }}>{title}</h3>
          <p style={{ margin: 0, fontSize: 12, color: "#241430b3" }}>{description}</p>
        </div>
        <span style={{ flexShrink: 0, fontSize: 10.5, fontWeight: 700, padding: "3px 9px", borderRadius: 999, background: accent, whiteSpace: "nowrap" }}>{datasetName}</span>
      </div>
      {style === "table" && (
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12, marginBottom: 14 }}>
          <thead>
            <tr>
              {["Region", "Revenue", "Growth"].map((h) => (
                <th key={h} style={{ textAlign: "left", fontSize: 10.5, textTransform: "uppercase", color: "#24143090", padding: "4px 6px", borderBottom: "1.5px solid #24143018" }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r[0]}>
                {r.map((cell, i) => (
                  <td key={i} style={{ padding: 6, borderBottom: "1px solid #24143012" }}>{cell}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      )}
      {style === "chart" && (
        <div style={{ display: "flex", alignItems: "flex-end", gap: 8, height: 80, marginBottom: 14 }}>
          {bars.map((h, i) => (
            <span key={i} style={{ flex: 1, background: accent, borderRadius: "4px 4px 0 0", height: h + "%" }} />
          ))}
        </div>
      )}
      {style === "cards" && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8, marginBottom: 14 }}>
          {cards.map(([label, value]) => (
            <div key={label} style={{ background: "#fff", borderRadius: 10, padding: 10 }}>
              <p style={{ margin: "0 0 2px", fontSize: 10, color: "#24143090" }}>{label}</p>
              <p style={{ margin: 0, fontSize: 15, fontWeight: 700 }}>{value}</p>
            </div>
          ))}
        </div>
      )}
      <button type="button" style={{ width: "100%", background: accent, border: "1.5px solid " + accent, borderRadius: 8, padding: 9, fontSize: 13, fontWeight: 600, cursor: "pointer" }}>Load sample data →</button>
    </div>
  );
}
